function verifyCode(e,o){console.log(o.length);if(o.length!=5)tellWrongCode();else{$.ajax({url:"/ThietBiDiDong/verify",method:"POST",data:{action:e,code:o},success:function(e){console.log(e);$("#verifyCode-response").html(e)}})}}function wrongOTP(e,o){const t=document.querySelector(e);t.querySelector(".otp-error").innerText=o}function tellVerifySuccessful(){document.querySelector(".otp-message").classList.add("active")}document.addEventListener("DOMContentLoaded",(function(){document.querySelector("#otp-form").addEventListener("submit",(function(e){e.preventDefault();const o=document.querySelector("#otp-form");var t=o.querySelector('input[name="a"]').value;var n=o.querySelector('input[name="email"]').value;var r=o.querySelector('input[name="action"]').value;var c=o.querySelector("#o1").value;var l=o.querySelector("#o2").value;var a=o.querySelector("#o3").value;var u=o.querySelector("#o4").value;var i=o.querySelector("#o5").value;if(c!=""&&l!=""&&a!=""&&u!=""&&i!=""){console.log(t);console.log(n);console.log(r);var s=parseInt(c+""+l+""+a+""+u+""+i);$.ajax({url:"verify",type:"POST",data:{a:t,email:n,action:r,otp:s},success:function(e){console.log(e);$("#verify-code-response").html(e)},error:function(e){}})}}));document.querySelector("#btn-resend").addEventListener("click",(function(e){e.preventDefault();location.reload()}))}));function openModal2(e){const o=document.querySelector(e);o.classList.add("active")}